package com.foodshare.dao;
import java.sql.*; import com.foodshare.database.DBConnection; import com.foodshare.model.NGORegistrationPOJO; import com.foodshare.service.PasswordUtil;
public class NgoDAO {
 public boolean registerNgo(NGORegistrationPOJO n){String q="INSERT INTO ngos(org_name,email,mobile,address,password_hash) VALUES(?,?,?,?,?)";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setString(1,n.getOrganizationName());p.setString(2,n.getEmail().trim().toLowerCase());p.setString(3,n.getMobile());p.setString(4,n.getAddress());p.setString(5,PasswordUtil.hash(n.getPassword()));return p.executeUpdate()==1;}catch(SQLException e){System.err.println("[NgoDAO] Registration failed: "+e.getMessage());return false;}}
 public NGORegistrationPOJO authenticateNgo(String login,String password){String q="SELECT id,org_name,email,mobile,address,password_hash FROM ngos WHERE lower(email)=lower(?) OR mobile=?";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setString(1,login.trim());p.setString(2,login.trim());try(ResultSet r=p.executeQuery()){if(!r.next()||!PasswordUtil.verify(password,r.getString("password_hash")))return null;NGORegistrationPOJO n=new NGORegistrationPOJO();n.setId(r.getInt("id"));n.setOrganizationName(r.getString("org_name"));n.setEmail(r.getString("email"));n.setMobile(r.getString("mobile"));n.setAddress(r.getString("address"));return n;}}catch(SQLException e){System.err.println("[NgoDAO] Login failed: "+e.getMessage());return null;}}
}
